import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, list[Any]]:
    expected_width = 12

    reader = csv.reader(io.StringIO(raw_csv.lstrip("\ufeff"), newline=""), delimiter=",", quotechar='"')
    records = []
    while True:
        try:
            record = next(reader)
        except StopIteration:
            break
        except csv.Error:
            continue
        if record and any(value.strip() for value in record):
            records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, record in enumerate(records) if len(record) >= expected_width),
        0,
    )
    header = list(records[header_index])
    if len(header) < expected_width:
        header.extend([""] * (expected_width - len(header)))

    max_width = max(expected_width, len(header), *(len(record) for record in records[header_index + 1:]))
    for i, value in enumerate(header):
        if not value.strip():
            header[i] = f"Column {i + 1}"
    while len(header) < max_width:
        header.append(f"Column {len(header) + 1}")

    rows = []
    for record in records[header_index + 1:]:
        row = list(record)
        if len(row) < max_width:
            row.extend([""] * (max_width - len(row)))
        rows.append(row)

    return {"columns": header, "rows": rows}
